import{_ as r,X as d,i as o,l as a}from"./chunks/plugin-vue_export-helper.CDld2K5w.js";const u=JSON.parse('{"title":"量化交易系统设计与实践","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md"}'),n={name:"guide/index.md"};function s(e,t,l,i,g,h){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="量化交易系统设计与实践" tabindex="-1">量化交易系统设计与实践 <a class="header-anchor" href="#量化交易系统设计与实践" aria-label="Permalink to &quot;量化交易系统设计与实践&quot;">​</a></h1><blockquote><p>20 大模块 · 121 个章节 · 交互式学习 · 含名词解释</p></blockquote><h2 id="📌-课程简介" tabindex="-1">📌 课程简介 <a class="header-anchor" href="#📌-课程简介" aria-label="Permalink to &quot;📌 课程简介&quot;">​</a></h2><p>本课程系统讲解量化交易的完整知识体系，涵盖金融数学基础、Python 编程实战、策略开发、回测框架、投资组合管理、实盘部署、衍生品与衍生品定价、固定收益、加密货币、市场微结构、宏观研究、风险管理、数据工程、策略生命周期、A 股本土化以及量化岗位求职准备等全链路内容。每个章节配有名词解释、Python 代码示例和交互式计算工具。</p><h2 id="模块概览" tabindex="-1">模块概览 <a class="header-anchor" href="#模块概览" aria-label="Permalink to &quot;模块概览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模块</th><th>内容</th><th>章节</th></tr></thead><tbody><tr><td><strong>模块一</strong></td><td>量化交易全景与行业认知</td><td>发展史、策略分类、量化思维、现实挑战、行业现状（2026）、职业地图、学习路线图</td></tr><tr><td><strong>模块二</strong></td><td>金融基础与数理工具</td><td>微观结构、资产定价、概率统计、时间序列、线性模型</td></tr><tr><td><strong>模块三</strong></td><td>Python 量化编程与数据工程</td><td>数据栈、数据清洗、性能优化、金融数据处理、可视化</td></tr><tr><td><strong>模块四</strong></td><td>回测框架与绩效评估</td><td>引擎原理、成本建模、绩效指标、陷阱与对策、统计检验、框架对比、事件驱动全栈、合成数据、多策略</td></tr><tr><td><strong>模块五</strong></td><td>策略开发工坊</td><td>因子投资、双均线、统计套利、CTA趋势、事件驱动、多因子</td></tr><tr><td><strong>模块六</strong></td><td>投资组合管理与优化</td><td>均值方差、风险平价、凯利准则、中性约束、VaR</td></tr><tr><td><strong>模块七</strong></td><td>执行算法与微观结构</td><td>订单类型、算法执行、做市策略、高频交易、成本分析（TCA）</td></tr><tr><td><strong>模块八</strong></td><td>机器学习与另类数据</td><td>监督学习、无监督、NLP、另类数据、过拟合防御</td></tr><tr><td><strong>模块九</strong></td><td>实盘部署与系统架构</td><td>系统设计、数据管道、券商接口、监控运维、合规监管</td></tr><tr><td><strong>模块十</strong></td><td>前沿专题与职业成长</td><td>强化学习、生成式 AI、暗池交易、职业路径、期末项目</td></tr><tr><td><strong>模块十一</strong></td><td>衍生品定价与波动率交易</td><td>Greeks、波动率曲面、奇异期权、树/有限差分、Monte Carlo、期权市场、隐含 vs 实际波动率、波动率交易、对冲实战、A 股场内期权</td></tr><tr><td><strong>模块十二</strong></td><td>固定收益</td><td>收益率曲线、久期凸度、利率互换与互换期权、信用利差、MBS 估值</td></tr><tr><td><strong>模块十三</strong></td><td>加密资产与去中心化金融</td><td>链上数据、资金费率、MEV、DEX 做市、永续合约</td></tr><tr><td><strong>模块十四</strong></td><td>微观结构进阶</td><td>订单流毒性、信息驱动模型、最优执行、LOB 动态、高频做市进阶</td></tr><tr><td><strong>模块十五</strong></td><td>宏观研究与资产配置</td><td>宏观因子、美联储政策、通胀传导、周期择时、跨资产联动</td></tr><tr><td><strong>模块十六</strong></td><td>风险管理</td><td>风险分解、极值理论与肥尾、压力测试、巴塞尔协议、尾部对冲</td></tr><tr><td><strong>模块十七</strong></td><td>数据工程</td><td>Tick 级数据库、实时 ETL、数据质量、批流一体、特征平台</td></tr><tr><td><strong>模块十八</strong></td><td>策略生命周期管理</td><td>策略孵化、纸面到实盘、A/B 测试、收益归因、策略退役</td></tr><tr><td><strong>模块十九</strong></td><td>A 股本土化专题</td><td>涨跌停板、IPO 制度、行业轮动、北向资金、政策事件</td></tr><tr><td><strong>模块二十</strong></td><td>量化岗位面试</td><td>数学统计、编码、金融、脑筋急转弯、模拟面试、真实面经、C++ 量化开发、简历与作品集</td></tr></tbody></table><h2 id="学习路线" tabindex="-1">学习路线 <a class="header-anchor" href="#学习路线" aria-label="Permalink to &quot;学习路线&quot;">​</a></h2><h3 id="入门阶段-0–2-个月" tabindex="-1">入门阶段（0–2 个月） <a class="header-anchor" href="#入门阶段-0–2-个月" aria-label="Permalink to &quot;入门阶段（0–2 个月）&quot;">​</a></h3><ol><li><strong>认知搭建</strong>（模块一）：建立量化交易整体认知，了解行业现状与职业路径</li><li><strong>数学基础</strong>（模块二）：掌握微观结构、资产定价、概率统计、时间序列、线性模型</li></ol><h3 id="工具阶段-2–4-个月" tabindex="-1">工具阶段（2–4 个月） <a class="header-anchor" href="#工具阶段-2–4-个月" aria-label="Permalink to &quot;工具阶段（2–4 个月）&quot;">​</a></h3><ol start="3"><li><strong>Python 数据栈</strong>（模块三）：熟练使用 NumPy / Pandas / 金融数据 API 与可视化</li></ol><h3 id="核心阶段-4–8-个月" tabindex="-1">核心阶段（4–8 个月） <a class="header-anchor" href="#核心阶段-4–8-个月" aria-label="Permalink to &quot;核心阶段（4–8 个月）&quot;">​</a></h3><ol start="4"><li><strong>回测与绩效</strong>（模块四）：掌握引擎原理、成本建模、绩效指标、陷阱与对策、统计检验、框架对比、事件驱动</li><li><strong>策略开发</strong>（模块五）：因子投资、双均线、统计套利、CTA、事件驱动、多因子</li><li><strong>组合管理</strong>（模块六）：均值方差、风险平价、凯利、约束优化、VaR</li></ol><h3 id="进阶阶段-8–12-个月" tabindex="-1">进阶阶段（8–12 个月） <a class="header-anchor" href="#进阶阶段-8–12-个月" aria-label="Permalink to &quot;进阶阶段（8–12 个月）&quot;">​</a></h3><ol start="7"><li><strong>执行与微结构</strong>（模块七）：订单类型、算法执行、做市、HFT、TCA</li><li><strong>机器学习与另类数据</strong>（模块八）：监督学习、无监督、NLP、另类数据、过拟合防御</li><li><strong>衍生品与波动率</strong>（模块十一）：Greeks、波动率曲面、蒙特卡洛、波动率交易、对冲、A 股场内期权</li><li><strong>固定收益</strong>（模块十二）：收益率曲线、久期凸度、IRS、MBS</li></ol><h3 id="高级阶段-12–18-个月" tabindex="-1">高级阶段（12–18 个月） <a class="header-anchor" href="#高级阶段-12–18-个月" aria-label="Permalink to &quot;高级阶段（12–18 个月）&quot;">​</a></h3><ol start="11"><li><strong>加密与微结构</strong>（模块十三 / 十四）：链上数据、资金费率、MEV、订单流毒性、LOB 动态</li><li><strong>宏观研究</strong>（模块十五）：宏观因子、美联储、通胀、周期、跨资产</li><li><strong>风险管理</strong>（模块十六）：风险分解、极值理论、压力测试、巴塞尔、尾部对冲</li></ol><h3 id="实战阶段-18–24-个月" tabindex="-1">实战阶段（18–24 个月） <a class="header-anchor" href="#实战阶段-18–24-个月" aria-label="Permalink to &quot;实战阶段（18–24 个月）&quot;">​</a></h3><ol start="14"><li><strong>数据工程</strong>（模块十七）：Tick 数据库、实时 ETL、数据质量、特征平台</li><li><strong>策略生命周期</strong>（模块十八）：孵化、纸面到实盘、A/B 测试、归因、退役</li><li><strong>A 股本土化</strong>（模块十九）：涨跌停、IPO、行业轮动、北向资金、政策事件</li></ol><h3 id="落地阶段" tabindex="-1">落地阶段 <a class="header-anchor" href="#落地阶段" aria-label="Permalink to &quot;落地阶段&quot;">​</a></h3><ol start="17"><li><strong>实盘部署</strong>（模块九）：系统设计、数据管道、券商接口、监控、合规</li><li><strong>前沿与项目</strong>（模块十）：强化学习、生成式 AI、暗池、职业路径、期末项目</li><li><strong>求职准备</strong>（模块二十）：数学/编码/金融/脑筋急转弯、模拟面试、C++ 量化开发、简历与作品集</li></ol><h2 id="开始学习" tabindex="-1">开始学习 <a class="header-anchor" href="#开始学习" aria-label="Permalink to &quot;开始学习&quot;">​</a></h2><p>从左侧边栏选择任意章节，或按顺序从模块一开始学习。<strong>建议路径</strong>：先打牢模块一至六的基础，再按兴趣方向选择衍生品（十一）、加密（十三）、微观结构（十四）、宏观（十五）或机器学习（模块八）作为进阶方向。</p>',23)])])}const b=r(n,[["render",s]]);export{u as __pageData,b as default};
